                            <th>Intent Level</th>
                            <th>Audience Type</th>
                            <th>Source</th>
                            <th>Membership Duration</th>
                            <th>Expected CVR</th>
                            <th>Best Bid Adjustment</th>
                        </tr>
                    </thead>
